mapper.select:
SELECT l.batch_no, o.order_id, o.reference_id, o.warehouse_id, l.seller_sku, l.supplier_batch_no, o.created_at, s.location_id, s.location_code, s.status, s.quantity FROM wms_inbound_order o JOIN wms_inbound_order_line l ON l.order_id = o.order_id LEFT JOIN wms_purchase_inspection i ON i.tenant_id = o.tenant_id AND i.batch_no = l.batch_no CROSS JOIN LATERAL ( SELECT NULL::varchar AS location_id, NULL::varchar AS location_code, 'PENDING_PUTAWAY' AS status, i.good_quantity - i.putaway_quantity AS quantity WHERE i.disposed_at IS NOT NULL
UNION ALL SELECT NULL, NULL, 'PENDING_INSPECTION', l.received_quantity WHERE i.disposed_at IS NULL UNION ALL SELECT NULL, NULL, 'QUARANTINED', i.defective_quantity WHERE i.disposed_at IS NOT NULL UNION ALL SELECT b.location_id, COALESCE(p.location_code, p.barcode), 'AVAILABLE', b.quantity FROM wms_batch_location_balance b JOIN wms_warehouse_location p ON p.location_id = b.location_id AND p.tenant_id = b.tenant_id WHERE b.tenant_id = o.tenant_id AND b.batch_no = l.batch_no
) s WHERE o.tenant_id = #{tenantId} AND o.reference_type = 'PURCHASE_RECEIPT' AND o.status = 'COMPLETED' AND l.batch_no IS NOT NULL AND s.quantity > 0 AND o.warehouse_id = #{filter.warehouseId} AND o.reference_id = #{filter.purchaseOrderId} AND s.location_id = #{filter.locationId} AND l.seller_sku = #{filter.sellerSku} AND l.batch_no = #{filter.batchNo} ORDER BY o.created_at, l.batch_no, s.status, s.location_code
